pub fn fromError(cause: anyerror) Entry {
    for (entries) |entry| if (entry.cause == cause) return entry;
    return .{ .cause = cause, .code = "file.internal_failure", .category = .internal, .message = "The file query could not complete. Preserve the original cause and source position for inspection; any emitted output is incomplete." };
}
